#include <bits/stdc++.h>
using namespace std;

long long memo[50];
int calls = 0;

long long fib(int n) {
    calls++;
    if (n < 2) return n;
    if (memo[n] != -1) return memo[n];
    return memo[n] = fib(n - 1) + fib(n - 2);
}

int main() {
    for (int i = 0; i < 50; i++) memo[i] = -1;
    cout << fib(10) << "\n" << calls << "\n";
    return 0;
}

