int main() {
    int coins[] = {4, 3, 1};
    int n = 6;
    int greedy = 0, rest = n;
    for (int c : coins) {
        greedy += rest / c;
        rest %= c;
    }
    const int INF = 1000000;
    int dp[7];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = INF;
        for (int c : coins)
            if (i >= c && dp[i - c] + 1 < dp[i]) dp[i] = dp[i - c] + 1;
    }
    cout << greedy << "\n" << dp[n] << "\n";
    return 0;
}

