#include <bits/stdc++.h>
using namespace std;

int main() {
    int A[] = {10, 9, 2, 5, 3, 7, 101, 18};
    int n = 8, L[8], prev[8], best = 0;
    for (int i = 0; i < n; i++) {
        L[i] = 1;
        prev[i] = -1;
        for (int j = 0; j < i; j++)
            if (A[j] < A[i] && L[j] + 1 > L[i]) {
                L[i] = L[j] + 1;
                prev[i] = j;
            }
        if (L[i] > L[best]) best = i;
    }
    int res[8], k = 0;
    for (int i = best; i != -1; i = prev[i]) res[k++] = A[i];
    for (int i = k - 1; i >= 0; i--) cout << res[i] << (i ? " " : "\n");
    return 0;
}

