#include <bits/stdc++.h>
using namespace std;

struct Job { int s, e, p; };

int main() {
    Job J[] = {{1, 3, 5}, {2, 5, 6}, {4, 6, 5}, {6, 7, 4}, {5, 8, 11}, {7, 9, 2}};
    int n = 6;   // đã sắp theo thời điểm kết thúc tăng dần
    int dp[7] = {};
    for (int i = 1; i <= n; i++) {
        int k = 0;   // số công việc cuối cùng kết thúc không muộn hơn s của i
        for (int j = i - 1; j >= 1; j--)
            if (J[j - 1].e <= J[i - 1].s) { k = j; break; }
        dp[i] = max(dp[i - 1], dp[k] + J[i - 1].p);
    }
    cout << dp[n] << "\n";
    return 0;
}

